// Whose gun this inventory item is: its weapon entity's decl name (+0x2e8 decl, +0x48 name) says gun_emily/crossbow_emily for
// Emily, anything else is Corvo's. 1 Emily, 0 Corvo, -1 unknown. The hip holster shows the same model (both avatars).
static int gun_owner_of(std::uintptr_t item) noexcept {
    std::uint32_t id{};std::uintptr_t game{},entity{},decl{},name{};std::array<char,128> text{};
    if(!read_self(item+8,&id,4) || id==0x3fff0010 || (id>>16)>=0x3fff || !read_self(image_base+0x39a5290,&game,8) || !d2vr::rig::pointer(game) ||
       !read_self(game+0x3130b0+(id>>16)*8,&entity,8) || !d2vr::rig::pointer(entity) || !read_self(entity+0x2e8,&decl,8) || !d2vr::rig::pointer(decl) ||
       !read_self(decl+0x48,&name,8) || !d2vr::rig::pointer(name) || !read_self(name,text.data(),text.size()-1)) return -1;
    std::string n(text.data());for(auto& c:n) c=static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if(n.find("weapon")==std::string::npos && n.find("gun")==std::string::npos && n.find("crossbow")==std::string::npos) return -1;
    return n.find("emily")!=std::string::npos?1:0;
}
// Aim direction = the barrel; the position stays the hand (the bore passes a few cm away: ~0.2 deg at the 30 m crosshair).
template<class P> static bool barrel_aim(P& p) noexcept {
    const auto model=left_gun_model.load();std::uintptr_t vt{};std::array<float,9> r{};
    if(!model || !read_self(model,&vt,8) || vt!=image_base+0x1b0d628 || !read_self(model+0x186c,r.data(),sizeof(r))) return false;
    const d2vr::Vec3 f{r[0],r[1],r[2]},l{r[3],r[4],r[5]},u{r[6],r[7],r[8]};
    for(const auto& v:{f,l,u}) if(!d2vr::finite(v) || std::abs(d2vr::length(v)-1)>.02) return false;
    if(std::abs(d2vr::dot(f,l))>.02 || std::abs(d2vr::dot(f,u))>.02) return false;
    p.basis={f,l,u};return true;
}
// Trim on top (both the crosshair and the shots): yaw left and pitch up in the aim frame, degrees. build/aim-offset "yaw pitch"
// or the "aim" test command tunes it live.
static std::atomic<float> aim_yaw_deg{0.f},aim_pitch_deg{0.f};
template<class P> static void aim_offset(P& p) noexcept {
    const double y=aim_yaw_deg.load()*3.14159265358979/180,q=aim_pitch_deg.load()*3.14159265358979/180;
    if(y==0 && q==0) return;
    const auto f=p.basis[0]*std::cos(y)+p.basis[1]*std::sin(y),l=p.basis[1]*std::cos(y)-p.basis[0]*std::sin(y),u=p.basis[2];
    p.basis={f*std::cos(q)+u*std::sin(q),l,u*std::cos(q)-f*std::sin(q)};
}
// Plan H2: the hand AIM ray (shots, powers, Blink aim, the crosshair) is smoothed by a speed-adaptive One Euro filter, once per displayed frame, in the player's anchor
// frame. Applied after the barrel/offset, before the clamp's origin guard. Never to the drawn hand, the sword or the interaction ray (takedown / Use targeting).
static void smooth_aim(d2vr::WorldTrackedPose& aim,const d2vr::GameCameraPose& anchor_pose,std::uint64_t frame_id,std::uint64_t pose_epoch,std::uint64_t reference_epoch) noexcept {
    if(!aim_smoothing_enabled) return;
    d2vr::WorldTrackedPose frame{};frame.position={anchor_pose.position[0],anchor_pose.position[1],anchor_pose.position[2]};
    for(unsigned axis=0;axis<3;++axis) frame.basis[axis]={anchor_pose.basis[axis*3],anchor_pose.basis[axis*3+1],anchor_pose.basis[axis*3+2]};
    const auto us=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());
    aim=aim_smoother.sample(aim,frame,frame_id,pose_epoch,reference_epoch,us);
}
// Small live creatures (bloodflies, rats; arkNPC or swarm agents, sim v383) are not in the world sweep the blade uses: a blade passing within 15 cm of one
// counts as a contact (headset v361: all 8 sword contacts were dead flies or the nest; the live wasps were never touched).
// Nearby small arkNPCs (render bounds under 1 m) are listed every 250 ms; each frame tests their bounds against the blade.
// Large=true: any live arkNPC (a person): the blade inside the render bounds picks the living target when a corpse was the nearest cast hit.
template<bool Large> static std::optional<std::pair<std::uintptr_t,d2vr::Vec3>> creature_on(d2vr::Vec3 a,d2vr::Vec3 b,UINT64 now,double reach) {
    static std::vector<std::uintptr_t> nearby;static UINT64 next{};static std::array<std::uintptr_t,0x3fff> registry{};
    const auto bounds=[](std::uintptr_t e)->std::optional<d2vr::NativeGrabBounds> {
        std::uint8_t state{};std::uintptr_t model{};std::array<float,8> box{};
        if(!read_self(e+0xd1,&state,1) || (state&8) || !read_self(e+0xf0,&model,8) || !d2vr::rig::pointer(model) || !read_self(model+0x1840,box.data(),32)) return {};
        const d2vr::NativeGrabBounds bb{{box[0],box[1],box[2]},{box[4],box[5],box[6]}};
        const auto ext=bb.maximum-bb.minimum;
        if(!d2vr::finite(ext) || ext.x<=0 || ext.y<=0 || ext.z<=0 || (!Large && std::max({ext.x,ext.y,ext.z})>=1.)) return {};
        return bb;};
    if(now>=next) {next=now+250;nearby.clear();std::uintptr_t game{};
        if(read_self(image_base+0x39a5290,&game,8) && d2vr::rig::pointer(game) && read_self(game+0x3130b0,registry.data(),sizeof(registry)))
            for(unsigned i=1;i<registry.size() && nearby.size()<24;++i) if(d2vr::rig::pointer(registry[i]) && (npc_entity(registry[i]) || (!Large && swarm_agent_entity(registry[i]))))
                if(const auto bb=bounds(registry[i]);bb && d2vr::length(bb->closest(a)-a)<4) nearby.push_back(registry[i]);
    }
    for(const auto e:nearby) if(const auto bb=bounds(e))
        for(int k=0;k<=8;++k) {const auto p=a+(b-a)*(k/8.);const auto c=bb->closest(p);if(d2vr::length(c-p)<=reach) return std::make_pair(e,c);}
    return {};
}
static std::optional<std::pair<std::uintptr_t,d2vr::Vec3>> small_creature_on(d2vr::Vec3 a,d2vr::Vec3 b,UINT64 now) {return creature_on<false>(a,b,now,.15);}
static std::optional<std::pair<std::uintptr_t,d2vr::Vec3>> live_npc_on(d2vr::Vec3 a,d2vr::Vec3 b,UINT64 now) {return creature_on<true>(a,b,now,.04);}
// Finger geometry per arm binding snapshot (finger_ik.hpp), rebuilt when the snapshot changes: the contact solve and the held-object
// seat (palm normal) share it. Render thread.
static std::shared_ptr<const d2vr::rig::NativeArmBindingSnapshot> finger_geometry_for;static std::array<std::optional<d2vr::rig::HandGeometry>,2> finger_geometry{};
// The hinge axes of that geometry in the arm-model space of the bind pose: what the full-body arm bends the finger bones about.
static std::array<std::optional<std::array<std::array<d2vr::Vec3,3>,5>>,2> finger_hinges{};
static std::array<bool,2> geometry_dump_due{};
static void refresh_finger_geometry() {
    const auto snapshot=arm_binding_cache.load();
    if(snapshot==finger_geometry_for) return;
    finger_geometry_for=snapshot;finger_geometry={};finger_hinges={};
    if(snapshot) for(unsigned side=0;side<2;++side) try {
        const auto& b=snapshot->bindings[side];
        finger_geometry[side]=d2vr::rig::hand_geometry(b.fingers.open,b.parents,b.finger_chains,b.palm,b.chain.wrist,b.bind_grip);
        finger_hinges[side]=d2vr::rig::hinge_axes(*finger_geometry[side],b.bind_grip);
        geometry_dump_due[side]=true; // written by flush_diag_dumps, off this timed path
    } catch(const std::invalid_argument&) {finger_geometry[side].reset();finger_hinges[side].reset();}
}
// The diagnostic files (artifacts/finger-geometry.jsonl once per binding, arm-palettes.jsonl twice a second during a hold) are written here, on the Present
// thread after the finger timers, through streams kept open: the geometry refresh and the arm upload only mark or copy (sim v527: the timed refresh
// peaked at 560-1016 us with a file open and flush inside it).
static void flush_diag_dumps() {
    static unsigned geometry_lines{};static std::ofstream geometry_out,palette_out;
    for(unsigned side=0;side<2;++side) if(geometry_dump_due[side]) {
        geometry_dump_due[side]=false;
        const auto snapshot=arm_binding_cache.load();
        if(!snapshot || !finger_geometry[side] || !finger_hinges[side] || geometry_lines>=8) continue;
        ++geometry_lines;const auto& b=snapshot->bindings[side];
        if(!geometry_out.is_open()) geometry_out.open(output_directory/L"finger-geometry.jsonl",std::ios::app);
        geometry_out<<d2vr::rig::geometry_json(side,*finger_geometry[side],*finger_hinges[side],b.bind_grip,
            {b.fingers.open[b.chain.wrist],b.fingers.open[b.finger_chains[0][0]],b.fingers.open[b.finger_chains[0][1]],b.fingers.open[b.finger_chains[0][2]]})<<'\n';
        geometry_out.flush();
    }
    std::optional<std::pair<unsigned,std::array<d2vr::rig::Transform,69>>> pending;
    {std::lock_guard<std::mutex> lock(palette_pending_mutex);pending.swap(palette_pending);}
    if(!pending) return;
    try {
        if(!palette_out.is_open()) palette_out.open(output_directory/L"arm-palettes.jsonl",std::ios::app);
        std::string line="{\"tick\":"+std::to_string(GetTickCount64())+",\"side\":"+std::to_string(pending->first)+",\"joints\":[";
        char number[32];
        for(unsigned j=0;j<69;++j) {
            line+=j?",[":"[";
            for(unsigned k=0;k<16;++k) {std::snprintf(number,sizeof number,"%.6g",static_cast<double>(pending->second[j].f[k]));line+=(k?",":"");line+=number;}
            line+="]";
        }
        palette_out<<line<<"]}"<<'\n';palette_out.flush();
    } catch(...) {}
}

