    const d2vr::Vec3 palm_local{d2vr::dot(offset,grip.basis[0]),d2vr::dot(offset,grip.basis[1]),d2vr::dot(offset,grip.basis[2])};
    if(!d2vr::clamp_probe_set_stale(clamp_probes[side],palm_local)) return;
