    if(!d2vr::finite(lo) || !d2vr::finite(hi) || hi.x<=lo.x || hi.y<=lo.y || hi.z<=lo.z || d2vr::length(hi-lo)>3) return;
    auto& p=probed_prop[side&1u];p.entity=entity;p.box=*box;p.axes=*ax;p.tick=GetTickCount64();
